function mkText(parent,str,opt={}){
  const t=figma.createText();
  t.fontName={family:"Inter",style:opt.weight||"Regular"};
  t.characters=str;
  t.fontSize=opt.size||14;
  t.fills=[{type:"SOLID",color:hex(opt.color||COLOR.ink)}];
  parent.appendChild(t);
  if(opt.w){t.resize(opt.w,t.height);}
  if(opt.align) t.textAlignHorizontal=opt.align;
  t.x=opt.x||0;t.y=opt.y||0;
  return t;
}
function mkRect(parent,opt={}){
  const r=figma.createRectangle();
  r.resize(opt.w||10,opt.h||10);
  r.fills= opt.color? [{type:"SOLID",color:hex(opt.color),opacity:opt.opacity!==undefined?opt.opacity:1}]:[];
  if(opt.radius) r.cornerRadius=opt.radius;
  if(opt.stroke){r.strokes=[{type:"SOLID",color:hex(opt.stroke)}];r.strokeWeight=opt.strokeWeight||1;}
  parent.appendChild(r);
  r.x=opt.x||0;r.y=opt.y||0;
  return r;
}
function mkEllipse(parent,opt={}){
  const e=figma.createEllipse();
  e.resize(opt.w||10,opt.h||10);
  e.fills=[{type:"SOLID",color:hex(opt.color||"#000000")}];
  parent.appendChild(e);
  e.x=opt.x||0;e.y=opt.y||0;
  return e;
}
