  const instance = node.createInstance? node.createInstance(): node.clone();
  parent.appendChild(instance);
  if(opt.w&&opt.h) instance.resize(opt.w,opt.h);
  instance.x=opt.x||0; instance.y=opt.y||0;
  return instance;
}
