async function buildTabBar(active){
  const f = figma.createComponent();
  f.name="C_TabBar_"+active; f.resize(375,83);
  f.fills=[{type:"SOLID",color:hex(COLOR.bg)}];
  mkRect(f,{x:0,y:0,w:375,h:1,color:COLOR.border});
  masterHolder.appendChild(f);
  const tabs=[
    {key:"Home", icon:"Icon_Nav_Home", iconActive:"Icon_Nav_Home_Active", label:"Home"},
    {key:"Explore", icon:"Icon_Nav_Explore", iconActive:"Icon_Nav_Explore_Active", label:"Explore"},
    {key:"Chat", icon:"Icon_Nav_Chat", iconActive:"Icon_Nav_Chat", label:"Chat"},
    {key:"Saved", icon:"Icon_Heart", iconActive:"Icon_Heart", label:"Saved"},
    {key:"Profile", icon:"Icon_Nav_Profile", iconActive:"Icon_Nav_Profile", label:"Profile"},
  ];
  const w=375/5;
  for(let i=0;i<tabs.length;i++){
    const t=tabs[i];
    const isActive = t.key===active;
    const iconKey = isActive? t.iconActive : t.icon;
    const ic = await inst(iconKey, f, {x:i*w+w/2-12, y:14, w:24,h:24});
    if(t.key==="Chat" && isActive){
      // add a tint overlay to indicate active via badge-colored dot under label too
    }
    const lbl = mkText(f, t.label, {x:i*w, y:44, size:11, weight: isActive?"Semi Bold":"Regular", color: isActive?COLOR.brand:COLOR.textTertiary});
    lbl.resize(w,14); lbl.textAlignHorizontal="CENTER";
    if(t.key==="Chat"){
      const badge = mkEllipse(f,{x:i*w+w/2+2,y:12,w:8,h:8,color:COLOR.badge});
      badge.visible = (active==="Chat_unread");
    }
  }
  f.x=1000; f.y=130*(["Home","Explore","Chat","Saved","Profile"].indexOf(active)+1);
  return f;
}
