async function swapPhoto(cardInstance, photoKey){
  // detach instance so we can edit its nested photo
  const detached = cardInstance.detachInstance ? cardInstance.detachInstance() : cardInstance;
  const photoSlot = detached.findOne(n=>n.name==="photo");
  if(photoSlot){
    const x=photoSlot.x,y=photoSlot.y,w=photoSlot.width,h=photoSlot.height;
    const idx = detached.children.indexOf(photoSlot);
