const COLOR = { brand:"#684DEC", textSecondary:"#6E7191", ink:"#15141A", surface:"#F6F5FA" };
function hex(h){h=h.replace('#','');return {r:parseInt(h.substr(0,2),16)/255,g:parseInt(h.substr(2,2),16)/255,b:parseInt(h.substr(4,2),16)/255};}
function mkText(parent,str,opt={}){
  const t=figma.createText();
  t.fontName={family:"Inter",style:opt.weight||"Regular"};
  t.characters=str; t.fontSize=opt.size||14;
  t.fills=[{type:"SOLID",color:hex(opt.color||COLOR.ink)}];
  parent.appendChild(t);
  if(opt.w){t.resize(opt.w,t.height);}
  if(opt.align) t.textAlignHorizontal=opt.align;
  t.x=opt.x||0;t.y=opt.y||0;
  return t;
}
function mkRect(parent,opt={}){
  const r=figma.createRectangle();
  r.resize(opt.w||10,opt.h||10);
  r.fills= opt.color? [{type:"SOLID",color:hex(opt.color),opacity:opt.opacity!==undefined?opt.opacity:1}]:[];
  if(opt.radius) r.cornerRadius=opt.radius;
  parent.appendChild(r); r.x=opt.x||0;r.y=opt.y||0;
  return r;
}
async function inst(key,parent,opt={}){
  const node = await figma.getNodeByIdAsync(M[key]);
  if(!node) return null;
  const instance = node.createInstance();
  parent.appendChild(instance);
  if(opt.w&&opt.h) instance.resize(opt.w,opt.h);
  instance.x=opt.x||0; instance.y=opt.y||0;
  return instance;
}
function mkFrame(name,w,h){
  const f=figma.createFrame();
  f.name=name; f.resize(w,h);
  f.fills=[{type:"SOLID",color:hex("#FFFFFF")}];
  f.clipsContent=true;
  return f;
}
async function addShell(frame){
  await inst("StatusBar", frame, {x:0,y:0,w:375,h:44});
  await inst("HomeIndicator", frame, {x:0,y:frame.height-34,w:375,h:34});
}
function findMaster(name){ return figma.root.findOne(n=>n.type==="COMPONENT" && n.name===name); }
async function useBtn(parent,label,x,y,w=327){
  const node = await figma.getNodeByIdAsync(M.Button);
  const i = node.createInstance(); parent.appendChild(i); i.resize(w,50); i.x=x;i.y=y;
  const t = i.findOne(n=>n.type==="TEXT"); if(t) t.characters=label;
  return i;
}
async function useSearch(parent,placeholder,x,y){
  const m = findMaster("C_SearchField");
  const i=m.createInstance(); parent.appendChild(i); i.resize(327,52); i.x=x;i.y=y;
  const t=i.findOne(n=>n.name==="placeholder"); if(t) t.characters=placeholder;
  return i;
}
