function setReaction(node, destFrame, trigger="ON_CLICK", action="NAVIGATE"){
  if(!node||!destFrame) return false;
  node.reactions = [{
    trigger:{type:trigger},
    actions:[{type:action, destinationId:destFrame.id, navigation:"NAVIGATE", transition:null, preserveScrollPosition:false}]
  }];
  return true;
}

// find a text/button node within a frame by partial name
function findByName(frame, matcher){
  return frame.findOne(n=> typeof matcher==="string" ? n.name===matcher : matcher(n.name));
}

